"use client"

import { cn } from "@/lib/utils"
import {
  Auth05AccountContent,
  Auth05Alternatives,
  Auth05Announcer,
  Auth05HelpLink,
  Auth05Intro,
  Auth05MethodBody,
  Auth05RememberDevice,
} from "./parts"
import type { Auth05Props } from "./types"
import { useAuth05 } from "./use-auth-05"

/**
 * 只有验证内容的版本：没有页面外壳，宽度跟随父容器，适合嵌进已有的登录布局（例如分屏登录页的右侧）。
 * 「其他验证方式」一律排在当前方式下方，单列；嵌入的容器通常很窄，不做两栏。
 */
function Auth05Panel(props: Auth05Props) {
  const auth = useAuth05(props)
  const { className, ...rootProps } = auth.rootProps
  const hasFooter = auth.showRememberDevice || Boolean(auth.helpHref)

  return (
    <div
      data-slot="auth-05-content"
      data-method={auth.method}
      data-state={auth.done ? "success" : "idle"}
      className={cn("flex w-full min-w-0 flex-col gap-6", className)}
      {...rootProps}
    >
      <div>
        <Auth05Intro auth={auth} defaultLevel={2} />
      </div>
      {/* 账号摘要放在标题之后：先说明要做什么，再说明是哪个账号 */}
      <div
        data-slot="auth-05-account"
        className="flex flex-wrap items-center gap-x-3 gap-y-1 rounded-lg border border-edge px-3 py-2"
      >
        <Auth05AccountContent auth={auth} />
      </div>
      <div>
        <Auth05MethodBody auth={auth} />
      </div>
      {!auth.done && auth.others.length > 0 && (
        <Auth05Alternatives
          auth={auth}
          className="border-t border-dashed border-edge pt-6"
        />
      )}
      {!auth.done && hasFooter && (
        <div className="flex flex-col gap-3">
          <Auth05RememberDevice auth={auth} />
          <div>
            <Auth05HelpLink auth={auth} />
          </div>
        </div>
      )}
      <Auth05Announcer auth={auth} />
    </div>
  )
}

export { Auth05Panel }

"use client"

import * as React from "react"

type UseControllableStateParams<T> = {
  /** 受控值；传入后组件不再维护内部状态 */
  prop?: T
  /** 非受控时的初始值 */
  defaultProp: T
  /** 值变化时回调（受控与非受控都会触发） */
  onChange?: (value: T) => void
}

/**
 * 同时支持受控与非受控的状态 hook。
 * 约定见 component-conventions 技能第 4 节：open/defaultOpen/onOpenChange 等成对 props 都用它实现。
 */
function useControllableState<T>({
  prop,
  defaultProp,
  onChange,
}: UseControllableStateParams<T>) {
  const [uncontrolled, setUncontrolled] = React.useState(defaultProp)
  const isControlled = prop !== undefined
  const value = isControlled ? prop : uncontrolled

  // 用 ref 保存最新的回调和值，保证 setValue 引用稳定
  const onChangeRef = React.useRef(onChange)
  const valueRef = React.useRef(value)
  React.useEffect(() => {
    onChangeRef.current = onChange
    valueRef.current = value
  })

  const setValue = React.useCallback(
    (next: React.SetStateAction<T>) => {
      const resolved =
        typeof next === "function"
          ? (next as (prev: T) => T)(valueRef.current)
          : next
      if (Object.is(resolved, valueRef.current)) return
      valueRef.current = resolved
      if (!isControlled) setUncontrolled(resolved)
      onChangeRef.current?.(resolved)
    },
    [isControlled],
  )

  return [value, setValue] as const
}

export { useControllableState }

import type * as React from "react"
import type { Auth05Labels } from "./config"

type Auth05Method = "passkey" | "totp" | "sms" | "recovery"

type Auth05AccountFields = {
  /** 邮箱，没有 `name`、`username` 时脱敏后显示。 */
  email?: string
  /** 短信验证用的手机号（11 位数字），脱敏后显示在短信面板；没有其他标识时也用它作账号摘要。 */
  phone?: string
  /** 显示名，原样显示，不脱敏；优先于邮箱和手机号。 */
  name?: string
  /** 用户名，原样显示，不脱敏；和 `name` 同时存在时作为小字补充。 */
  username?: string
  /** 头像图片；没有时显示实际显示的那个名字的首字。 */
  avatar?: string
}

/**
 * 已通过第一步认证的账号。`email`、`phone`、`name`、`username` 至少要有一个：
 * 用联合类型表达，漏传时在编译期就能发现；运行时仍会兜底（摘要为空、头像显示 ?），不会崩溃。
 */
type Auth05Account = Auth05AccountFields &
  (
    | { email: string }
    | { phone: string }
    | { name: string }
    | { username: string }
  )

type Auth05RecoveryCode = {
  /**
   * 掩码，`X` 代表一个字母或数字，其他字符原样插入，如 `"XXXX-XXXX"`、`"XXXXX-XXXXX"`。
   * 传 `false` 不做格式化：输入框里是什么就是什么，提交时只去掉首尾空白。
   * @default "XXXX-XXXX"
   */
  format?: string | false
  /**
   * 输入时就把输入框里的值转成大写（不是只靠 CSS 显示），提交的值也是大写。
   * 有掩码时默认 `true`，`format` 为 `false` 时默认 `false`（原样输入）。
   */
  uppercase?: boolean
  /**
   * 最大字符数，仅在 `format` 为 `false` 时生效；有掩码时长度由掩码决定。
   * 按输入框里的原始字符计数，连字符和空格都算；长度判断用去掉首尾空白之后的值。
   * 超过时不截断，输入框下方显示错误并禁止提交，删回范围内错误就消失。
   */
  maxLength?: number
  /** 输入框占位文字。@default 根据 format 生成 */
  placeholder?: string
}

type Auth05Props = Omit<React.ComponentProps<"div">, "onSuccess"> & {
  /** 已通过第一步认证的账号。 */
  account: Auth05Account
  /** 可用的验证方式，顺序即「其他验证方式」列表的顺序。@default ["passkey","totp","sms","recovery"] */
  methods?: readonly Auth05Method[]
  /**
   * 通行密钥验证。在这里调用 WebAuthn；失败时抛出 Error。
   * `name` 为 `NotAllowedError` 的错误会被当作「已取消」，其他错误显示 `message`。
   */
  onPasskey?: () => Promise<void>
  /** 发送短信验证码，失败时抛出 Error。 */
  onSendCode?: () => Promise<void>
  /** 验证验证码或恢复码，失败时抛出 Error。 */
  onVerify?: (values: {
    method: Exclude<Auth05Method, "passkey">
    code: string
  }) => Promise<void>
  /** 验证成功后的通知。 */
  onSuccess?: (values: {
    method: Auth05Method
    rememberDevice: boolean
  }) => void
  /** 点击「切换账号」。 */
  onSwitchAccount?: () => void
  /** 「联系管理员」链接地址；不传时不显示这个入口。 */
  helpHref?: string
  /** 覆盖浏览器能力检测，方便演示和测试；不传时在挂载后检测 `PublicKeyCredential`。 */
  passkeySupported?: boolean
  /** 验证码位数。@default 6 */
  codeLength?: number
  /** 短信重发间隔秒数。@default 60 */
  resendSeconds?: number
  /** 备用码的格式；不传时为 `XXXX-XXXX`。 */
  recoveryCode?: Auth05RecoveryCode
  /**
   * 是否显示「记住此设备」开关。后端不支持时设为 `false`：开关不渲染，`onSuccess` 里的 `rememberDevice` 固定为 `false`。
   * @default true
   */
  showRememberDevice?: boolean
  /**
   * 主标题「验证你的身份」用的标题级别。嵌进已有页面时，宿主页通常已有 h1，用 2 或 3 保持层级连续。
   * @default Auth05 为 1，Auth05Panel 为 2
   */
  headingLevel?: 1 | 2 | 3
  /** 品牌名称和标志。 */
  brand?: { name: string; logo?: React.ReactNode }
  /** 覆盖默认中文文案。 */
  labels?: Partial<Auth05Labels>
  /** 受控的当前验证方式。 */
  method?: Auth05Method
  /** 初始验证方式。@default 第一个可用方式 */
  defaultMethod?: Auth05Method
  /** 验证方式变化通知。 */
  onMethodChange?: (method: Auth05Method) => void
  /** 受控的「记住此设备」。 */
  rememberDevice?: boolean
  /** 初始的「记住此设备」。@default false */
  defaultRememberDevice?: boolean
  onRememberDeviceChange?: (value: boolean) => void
}

export type { Auth05Account, Auth05Method, Auth05Props, Auth05RecoveryCode }

import type { Auth05Account, Auth05RecoveryCode } from "./types"

/** 邮箱脱敏：保留前 3 位，如 lin***@example.com；不足 3 位时只保留首位。 */
function maskEmail(email: string) {
  const at = email.lastIndexOf("@")
  if (at < 1) return email
  const name = email.slice(0, at)
  const keep = name.length > 3 ? 3 : 1
  return `${name.slice(0, keep)}***${email.slice(at)}`
}

/** 手机号脱敏：138 **** 8000。 */
function maskPhone(phone: string) {
  const digits = phone.replace(/\D/g, "")
  if (digits.length !== 11) return phone
  return `${digits.slice(0, 3)} **** ${digits.slice(7)}`
}

/**
 * 账号摘要的显示规则：
 * 有 name 或 username 就原样显示（不脱敏）；否则脱敏邮箱，再否则脱敏手机号。
 * 头像首字取实际显示的那个名字，用 Array.from 按字符取，避免把中文或表情拆坏。
 */
function describeAccount(account: Partial<Auth05Account>) {
  const name = account.name?.trim()
  const username = account.username?.trim()
  const email = account.email?.trim()
  const phone = account.phone?.trim()
  let primary = ""
  let secondary: string | undefined
  let masked = false
  if (name || username) {
    primary = name || username || ""
    if (name && username)
      secondary = username.startsWith("@") ? username : `@${username}`
  } else if (email) {
    primary = maskEmail(email)
    masked = true
  } else if (phone) {
    primary = maskPhone(phone)
    masked = true
  }
  const source = name || username || email || phone || ""
  const initial = (Array.from(source.replace(/^@/, ""))[0] ?? "?").toUpperCase()
  return { primary, secondary, masked, initial }
}

const DEFAULT_RECOVERY_FORMAT = "XXXX-XXXX"

type RecoveryRule = {
  /** 掩码；`false` 表示不格式化。 */
  format: string | false
  uppercase: boolean
  maxLength?: number
}

/** 整理 recoveryCode 配置：没有 `X` 的掩码没有意义，退回默认。 */
function resolveRecoveryRule(options?: Auth05RecoveryCode): RecoveryRule {
  const format =
    options?.format === false
      ? false
      : typeof options?.format === "string" && options.format.includes("X")
        ? options.format
        : DEFAULT_RECOVERY_FORMAT
  const maxLength =
    typeof options?.maxLength === "number" && options.maxLength > 0
      ? Math.floor(options.maxLength)
      : undefined
  return {
    format,
    // 不格式化时默认原样输入，显式设为 true 才转大写
    uppercase: options?.uppercase ?? format !== false,
    maxLength,
  }
}

/**
 * 恢复码整理。有掩码：去掉非字母数字，按掩码逐位填入（`X` 取一个字符，其他字符原样插入，
 * 输入没写到那一位时不提前插入分隔符，所以退格不会卡在分隔符上），多出的字符不进入。
 * 无掩码：只按 uppercase 转大写，其余原样返回；超过 maxLength 也不截断，由 recoveryOverflow 报告。
 */
function formatRecoveryCode(raw: string, rule: RecoveryRule) {
  if (rule.format === false) return rule.uppercase ? raw.toUpperCase() : raw
  let clean = raw.replace(/[^a-zA-Z0-9]/g, "")
  if (rule.uppercase) clean = clean.toUpperCase()
  let output = ""
  let index = 0
  for (const char of rule.format) {
    if (index >= clean.length) break
    if (char === "X") output += clean[index++]
    else output += char
  }
  return output
}

/** 掩码里能填的字符数（`X` 的个数）。 */
function recoveryCapacity(format: string) {
  return Array.from(format).filter((char) => char === "X").length
}

/** 有掩码时，输入里被丢掉的字符数（字母数字比掩码容量多出来的部分）；无掩码或没有多出时为 0。 */
function recoveryDropped(raw: string, rule: RecoveryRule) {
  if (rule.format === false) return 0
  const length = raw.replace(/[^a-zA-Z0-9]/g, "").length
  return Math.max(0, length - recoveryCapacity(rule.format))
}

/**
 * 无掩码且设了 maxLength 时，输入是否超长：长度按去掉首尾空白后的原始字符数计（连字符、空格都算）。
 * 超长返回 `{ max, length }`，否则返回 null。
 */
function recoveryOverflow(code: string, rule: RecoveryRule) {
  if (rule.format !== false || !rule.maxLength) return null
  const length = code.trim().length
  return length > rule.maxLength ? { max: rule.maxLength, length } : null
}

/** 恢复码是否可以提交：有掩码要填满；无掩码要求非空，且设了 maxLength 时不能超长。 */
function isRecoveryComplete(code: string, rule: RecoveryRule) {
  return rule.format === false
    ? code.trim().length > 0 && !recoveryOverflow(code, rule)
    : code.length === rule.format.length
}

export {
  describeAccount,
  formatRecoveryCode,
  isRecoveryComplete,
  maskEmail,
  maskPhone,
  recoveryCapacity,
  recoveryDropped,
  recoveryOverflow,
  resolveRecoveryRule,
}
export type { RecoveryRule }

"use client"
import * as React from "react"
/** 用同步锁拦截自动提交与回车的重复请求。 */
function useAsyncAction(fallback: string) {
  const lock = React.useRef(false)
  const [pending, setPending] = React.useState(false)
  const [error, setError] = React.useState("")
  async function run(action: () => Promise<void>) {
    if (lock.current) return false
    lock.current = true
    setPending(true)
    setError("")
    try {
      await action()
      return true
    } catch (caught) {
      setError(caught instanceof Error ? caught.message : fallback)
      return false
    } finally {
      lock.current = false
      setPending(false)
    }
  }
  return { pending, error, setError, run }
}
export { useAsyncAction }

"use client"

import {
  InputOTP,
  InputOTPGroup,
  InputOTPSlot,
} from "@/components/ui/input-otp"

/** 6 位数字验证码输入；写法与 auth-03 保持一致：整串粘贴、满位自动提交、错误态同步到每个格子。 */
function Auth05CodeInput({
  length,
  value,
  error,
  describedBy,
  label,
  disabled,
  onChange,
  onComplete,
}: {
  length: number
  value: string
  error: boolean
  describedBy?: string
  label: string
  disabled: boolean
  onChange: (value: string) => void
  onComplete: (value: string) => void
}) {
  return (
    <div data-slot="auth-05-code-input">
      <InputOTP
        maxLength={length}
        value={value}
        onChange={onChange}
        onComplete={onComplete}
        pattern="^[0-9]*$"
        autoComplete="one-time-code"
        inputMode="numeric"
        aria-label={label}
        aria-invalid={error || undefined}
        aria-describedby={describedBy}
        disabled={disabled}
        containerClassName="w-full"
      >
        <InputOTPGroup className="w-full">
          {Array.from({ length }, (_, index) => (
            <InputOTPSlot
              key={index}
              index={index}
              aria-invalid={error || undefined}
              className="h-9 min-w-0 flex-1 border-edge text-base data-[active=true]:border-foreground/25 data-[active=true]:bg-muted/40 data-[active=true]:ring-0 pointer-coarse:h-11"
            />
          ))}
        </InputOTPGroup>
      </InputOTP>
    </div>
  )
}

export { Auth05CodeInput }

"use client"

import * as React from "react"
import { Loader2 } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { cn } from "@/lib/utils"
import { formatLabel, type Auth05Labels } from "./config"
import { Auth05CodeInput } from "./form-parts"
import {
  formatRecoveryCode,
  isRecoveryComplete,
  maskPhone,
  recoveryCapacity,
  recoveryDropped,
  recoveryOverflow,
  resolveRecoveryRule,
} from "./mask"
import type { Auth05Props } from "./types"
import { useAsyncAction } from "./use-auth-form"

type PanelBase = {
  labels: Auth05Labels
  /** 请求进行中时通知父级，用于锁定「其他验证方式」，避免结果落在已卸载的面板上。 */
  onBusyChange: (busy: boolean) => void
}

function useBusy(busy: boolean, onBusyChange: (busy: boolean) => void) {
  React.useEffect(() => {
    onBusyChange(busy)
    return () => onBusyChange(false)
  }, [busy, onBusyChange])
}

type PasskeyStatus = "idle" | "waiting" | "cancelled" | "error"

/** 通行密钥：WebAuthn 由接入方在 onPasskey 里实现，这里只按回调结果显示状态。 */
function Auth05PasskeyPanel({
  labels,
  onBusyChange,
  supported,
  onPasskey,
  onDone,
  suggestion,
}: PanelBase & {
  /** `null` 表示尚未检测（服务端渲染和水合期间）。 */
  supported: boolean | null
  onPasskey?: () => Promise<void>
  onDone: () => void
  suggestion?: { name: string; onSelect: () => void }
}) {
  const [status, setStatus] = React.useState<PasskeyStatus>("idle")
  const [message, setMessage] = React.useState("")
  const lock = React.useRef(false)
  // 忙状态在事件里同步通知父级（不经过 effect），列表在同一次渲染里就被锁住；卸载时兜底解锁
  React.useEffect(() => () => onBusyChange(false), [onBusyChange])

  async function start() {
    if (lock.current || supported === false) return
    lock.current = true
    onBusyChange(true)
    setStatus("waiting")
    setMessage("")
    try {
      if (!onPasskey) throw new Error(labels.failed)
      await onPasskey()
      onDone()
    } catch (caught) {
      // 用户关闭系统弹窗、超时或拒绝时，WebAuthn 统一抛 NotAllowedError，不算故障。
      if ((caught as { name?: string } | null)?.name === "NotAllowedError") {
        setStatus("cancelled")
      } else {
        setStatus("error")
        setMessage(caught instanceof Error ? caught.message : labels.failed)
      }
    } finally {
      lock.current = false
      onBusyChange(false)
    }
  }

  const waiting = status === "waiting"
  // 状态文字放在始终存在的 aria-live 容器里，变化时才会被播报
  const liveText =
    supported === false
      ? labels.passkeyUnsupported
      : waiting
        ? labels.passkeyWaiting
        : status === "cancelled"
          ? labels.passkeyCancelled
          : ""

  return (
    <div data-slot="auth-05-passkey" data-status={status} className="space-y-4">
      <p className="text-sm leading-7 text-muted-foreground">
        {labels.passkeyDescription}
      </p>
      <p
        aria-live="polite"
        data-slot="auth-05-passkey-status"
        className="min-h-5 text-sm text-muted-foreground"
      >
        {liveText}
      </p>
      {status === "error" && message && (
        <p role="alert" className="text-xs text-destructive">
          {message}
        </p>
      )}
      <Button
        type="button"
        size="lg"
        className="w-full"
        disabled={waiting || supported === false}
        aria-busy={waiting || undefined}
        onClick={() => void start()}
      >
        {waiting ? (
          <>
            <Loader2
              aria-hidden
              className="animate-spin motion-reduce:animate-none"
            />
            {labels.passkeyWaitingButton}
          </>
        ) : (
          labels.passkeyAction
        )}
      </Button>
      {supported === false && suggestion && (
        <Button
          type="button"
          size="lg"
          variant="outline"
          className="w-full"
          onClick={suggestion.onSelect}
        >
          {formatLabel(labels.passkeySuggest, { method: suggestion.name })}
        </Button>
      )}
    </div>
  )
}

/** 验证器 App（totp）与短信共用：6 位数字，满位自动提交；短信多一步「发送」和倒计时。 */
function Auth05CodePanel({
  labels,
  onBusyChange,
  kind,
  length,
  phone,
  resendSeconds,
  onSendCode,
  onVerify,
  onDone,
}: PanelBase & {
  kind: "totp" | "sms"
  length: number
  phone?: string
  resendSeconds: number
  onSendCode?: () => Promise<void>
  onVerify?: Auth05Props["onVerify"]
  onDone: () => void
}) {
  const id = React.useId()
  const [code, setCode] = React.useState("")
  const [sent, setSent] = React.useState(false)
  const [deadline, setDeadline] = React.useState(0)
  const [remaining, setRemaining] = React.useState(0)
  const sending = useAsyncAction(labels.failed)
  const verifying = useAsyncAction(labels.failed)
  const pending = sending.pending || verifying.pending
  useBusy(pending, onBusyChange)
  const masked = phone ? maskPhone(phone) : ""

  React.useEffect(() => {
    if (!deadline) return
    const tick = () =>
      setRemaining(Math.max(0, Math.ceil((deadline - Date.now()) / 1000)))
    tick()
    const timer = window.setInterval(tick, 250)
    return () => window.clearInterval(timer)
  }, [deadline])

  async function send() {
    if (pending || remaining > 0) return
    const ok = await sending.run(async () => {
      if (!onSendCode) throw new Error(labels.failed)
      await onSendCode()
    })
    if (!ok) return
    setSent(true)
    setCode("")
    verifying.setError("")
    const seconds = Math.max(0, resendSeconds)
    setRemaining(seconds)
    // 仅在发送成功的事件回调中读取时间，不参与服务端渲染。
    setDeadline(Date.now() + seconds * 1000)
  }

  async function verify(value: string) {
    if (pending || value.length !== length) return
    const ok = await verifying.run(async () => {
      if (!onVerify) throw new Error(labels.failed)
      await onVerify({ method: kind, code: value })
    })
    if (ok) onDone()
  }

  const showCode = kind === "totp" || sent
  const description =
    kind === "totp"
      ? formatLabel(labels.totpDescription, { length })
      : formatLabel(labels.smsDescription, { phone: masked })

  return (
    <form
      noValidate
      data-slot={`auth-05-${kind}`}
      onSubmit={(event) => {
        event.preventDefault()
        void verify(code)
      }}
      className="space-y-4"
    >
      <p className="text-sm leading-7 text-muted-foreground">{description}</p>
      {kind === "sms" && (
        <>
          <Button
            type="button"
            size="lg"
            variant={sent ? "outline" : "default"}
            className="w-full"
            disabled={pending || remaining > 0}
            onClick={() => void send()}
          >
            {sending.pending
              ? labels.smsSending
              : remaining > 0
                ? formatLabel(labels.smsCountdown, { seconds: remaining })
                : sent
                  ? labels.smsResend
                  : labels.smsSend}
          </Button>
          <p
            aria-live="polite"
            className="min-h-5 font-mono text-xs text-muted-foreground"
          >
            {sent ? formatLabel(labels.smsSent, { phone: masked }) : ""}
          </p>
          {sending.error && (
            <p role="alert" className="text-xs text-destructive">
              {sending.error}
            </p>
          )}
        </>
      )}
      {showCode && (
        <>
          <div className="space-y-2">
            <Auth05CodeInput
              length={length}
              value={code}
              label={formatLabel(labels.code, { length })}
              disabled={pending}
              error={!!verifying.error}
              describedBy={verifying.error ? `${id}-error` : undefined}
              onChange={(value) => {
                setCode(value)
                verifying.setError("")
              }}
              onComplete={(value) => void verify(value)}
            />
            {verifying.error && (
              <p
                role="alert"
                id={`${id}-error`}
                className="text-xs text-destructive"
              >
                {verifying.error}
              </p>
            )}
          </div>
          <Button
            type="submit"
            size="lg"
            className="w-full"
            disabled={pending || code.length !== length}
          >
            {verifying.pending ? labels.verifying : labels.verify}
          </Button>
        </>
      )}
    </form>
  )
}

/**
 * 恢复码：默认输入时自动转大写并插入短横线（XXXX-XXXX），格式可通过 recoveryCode 配置，也可以完全不格式化。
 * 内容不会被悄悄改掉：不格式化时超过 maxLength 保留原样并报错、禁止提交；
 * 有掩码时多出的字符会被丢掉，并给出一条会被读屏播报的提示。
 */
function Auth05RecoveryPanel({
  labels,
  onBusyChange,
  onVerify,
  onDone,
  recoveryCode,
}: PanelBase & {
  onVerify?: Auth05Props["onVerify"]
  onDone: () => void
  recoveryCode?: Auth05Props["recoveryCode"]
}) {
  const rule = resolveRecoveryRule(recoveryCode)
  const masked = rule.format !== false
  const id = React.useId()
  const [code, setCode] = React.useState("")
  const complete = isRecoveryComplete(code, rule)
  // 超长是从当前值直接算出来的：删回范围内错误自然消失，不用另外清除
  const overflow = recoveryOverflow(code, rule)
  const [notice, setNotice] = React.useState("")
  const placeholder =
    recoveryCode?.placeholder ??
    formatLabel(labels.recoveryPlaceholder, { format: rule.format || "" })
  const [localError, setLocalError] = React.useState("")
  const verifying = useAsyncAction(labels.failed)
  useBusy(verifying.pending, onBusyChange)
  const overflowError = overflow
    ? formatLabel(labels.recoveryTooLong, overflow)
    : ""
  const error = overflowError || localError || verifying.error
  const inputRef = React.useRef<HTMLInputElement>(null)

  async function submit() {
    if (verifying.pending) return
    if (overflow) {
      // 回车提交时按钮虽然禁用也可能走到这里：拦下并把焦点还给输入框
      inputRef.current?.focus()
      return
    }
    if (!complete) {
      setLocalError(
        masked
          ? formatLabel(labels.recoveryError, { format: rule.format as string })
          : labels.recoveryEmpty,
      )
      return
    }
    const ok = await verifying.run(async () => {
      if (!onVerify) throw new Error(labels.failed)
      // 不格式化时只去掉首尾空白，其余原样提交
      await onVerify({ method: "recovery", code: code.trim() })
    })
    if (ok) onDone()
  }

  return (
    <form
      noValidate
      data-slot="auth-05-recovery"
      onSubmit={(event) => {
        event.preventDefault()
        void submit()
      }}
      className="space-y-4"
    >
      <p className="text-sm leading-7 text-muted-foreground">
        {labels.recoveryDescription}
      </p>
      <div className="space-y-2">
        <label
          htmlFor={`${id}-input`}
          className="text-xs text-muted-foreground"
        >
          {labels.recoveryLabel}
        </label>
        <Input
          ref={inputRef}
          id={`${id}-input`}
          value={code}
          onChange={(event) => {
            const raw = event.target.value
            setCode(formatRecoveryCode(raw, rule))
            // 有掩码时多出来的字符不会进入输入框，要让用户知道；下一次输入重新计算，没有多出就清除
            const dropped = recoveryDropped(raw, rule)
            setNotice(
              dropped > 0 && rule.format !== false
                ? formatLabel(labels.recoveryTrimmed, {
                    count: recoveryCapacity(rule.format),
                  })
                : "",
            )
            setLocalError("")
            verifying.setError("")
          }}
          placeholder={placeholder}
          autoComplete="off"
          autoCapitalize={rule.uppercase ? "characters" : "off"}
          autoCorrect="off"
          spellCheck={false}
          disabled={verifying.pending}
          aria-invalid={error ? true : undefined}
          aria-describedby={`${id}-note${notice ? ` ${id}-notice` : ""}${error ? ` ${id}-error` : ""}`}
          className={cn(
            "h-9 font-mono focus-visible:border-foreground/25 focus-visible:bg-background focus-visible:ring-0 aria-invalid:focus-visible:ring-3 pointer-coarse:h-11",
            masked && "tracking-widest",
          )}
        />
        <p id={`${id}-note`} className="text-xs text-muted-foreground">
          {labels.recoveryNote}
        </p>
        {/* 常驻的播报区：内容变化时读屏才会播报；没有内容时不占位 */}
        <p
          id={`${id}-notice`}
          role="status"
          data-slot="auth-05-recovery-notice"
          className="text-xs text-muted-foreground empty:hidden"
        >
          {notice}
        </p>
        {error && (
          <p
            role="alert"
            id={`${id}-error`}
            className="text-xs text-destructive"
          >
            {error}
          </p>
        )}
      </div>
      <Button
        type="submit"
        size="lg"
        className="w-full"
        disabled={verifying.pending || !complete}
      >
        {verifying.pending ? labels.verifying : labels.verify}
      </Button>
    </form>
  )
}

