      ) : method === "passkey" ? (
        <Auth05PasskeyPanel
          labels={labels}
          onBusyChange={setBusy}
          supported={supported}
          onPasskey={auth.onPasskey}
          onDone={complete}
          suggestion={
            suggestedMethod
