        <Auth05RecoveryPanel
          labels={labels}
          onBusyChange={setBusy}
          onVerify={auth.onVerify}
          onDone={complete}
          recoveryCode={auth.recoveryCode}
        />
      ) : (
        <Auth05CodePanel
          labels={labels}
          onBusyChange={setBusy}
          kind={method}
          length={auth.codeLength}
          phone={auth.account.phone}
          resendSeconds={auth.resendSeconds}
          onSendCode={auth.onSendCode}
          onVerify={auth.onVerify}
          onDone={complete}
        />
      )}
    </motion.div>
  )
}

